// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Reentrance} from "../src/Reentrance.sol";

contract InvMutTest is Test {
    Reentrance c;
    function setUp() public { c = new Reentrance(); }
    function testFuzz_property(uint128 deposit, uint128 withdrawAmount) public {
        vm.assume(deposit > 0);
        vm.assume(withdrawAmount > 0 && withdrawAmount <= deposit);

        address alice = makeAddr("alice");
        vm.deal(alice, deposit);
        vm.prank(alice);
        c.addToBalance{value: deposit}();

        Receiver helper = new Receiver();
        vm.deal(address(helper), deposit);
        vm.prank(address(helper));
        c.addToBalance{value: deposit}();

        uint256 contractBalBefore = address(c).balance;
        uint256 helperBalBefore = address(helper).balance;

        vm.prank(address(helper));
        c.withdrawBalance();

        uint256 expectedWithdrawal = c.getBalance(address(helper));
        bool balanceCleared = c.getBalance(address(helper)) == 0;
        assertTrue(balanceCleared);
    }
}

contract Receiver {
    receive() external payable {}
}
